import random
from random import choice, randint, random as _random

def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n < 3:
        return 'C'

    # Basic counts
    my_c = 0
    op_c = 0
    cc = cd = dc = dd = 0
    for (a, b) in history:
        if a == 'C':
            my_c += 1
        else:
            pass
        if b == 'C':
            op_c += 1
        else:
            pass
        if a == 'C' and b == 'C':
            cc += 1
        elif a == 'C' and b == 'D':
            cd += 1
        elif a == 'D' and b == 'C':
            dc += 1
        else:
            dd += 1

    # Last actions
    last_me, last_op = history[-1]
    prev_me, prev_op = history[-2]

    # Detect likely simple patterns in opponent
    # Opponent cooperation rate
    op_rate = op_c / n
    my_rate = my_c / n

    # Immediate retaliation/forgiveness style: if opponent just defected and I cooperated last,
    # defect now to punish/avoid exploitation, unless very late and opponent has been mostly cooperative.
    if last_op == 'D':
        # If opponent defected while I cooperated, punish
        if last_me == 'C':
            if n > 90 and op_rate > 0.75:
                return 'C'
            return 'D'
        # If opponent defected after I defected too, maybe avoid endless DD if opponent mostly cooperates
        if last_me == 'D':
            if op_rate > 0.65 and n > 20:
                return 'C'
            return 'D'

    # If opponent just cooperated:
    if last_op == 'C':
        # Be cooperative by default, but occasionally exploit very cooperative opponents late.
        if n > 85 and op_rate > 0.85 and my_rate < 0.95:
            # Late-game exploitation against always-cooperative-ish opponents
            return 'D'
        # If opponent cooperated after I defected, don't punish further: reciprocate cooperation
        return 'C'

    return 'C'
